var pa = PhaseManager.get_current_phase_instance().pending_assignments
var out = []
for a in pa:
	out.append(str(a.get("weapon_id", "")))
print("[cus11e orb] declared: ", out)
return ",".join(out).to_lower().contains("auriferous")

var D = load("res://scripts/codex/custodes/CustodesDetachments.gd")
var fx = D.hit_effects(GameState.state.units["U_GRETCHIN_C"], GameState.state.units["U_WITCHSEEKERS_D"], false)
for c in fx:
	if str(c.get("kind", "")) == "minus_one" and str(c.get("source", "")).contains("Blinding Light"):
		return true
return false
